+
 /** Parse a size such as "1.5 kB" into bytes. See README.md for the units. */
 export function parseSize(text: string): number {
-  throw new Error("not implemented");
+  const match = typeof text === "string" ? SIZE_PATTERN.exec(text) : null;
+  if (!match) {
+    throw new RangeError(`invalid size: ${JSON.stringify(text)}`);
+  }
+  const unit = match[2] === "" ? 1 : UNITS[match[2].toLowerCase()];
+  if (unit === undefined) {
+    throw new RangeError(`invalid size: unknown unit in ${JSON.stringify(text)}`);
+  }
+  return Math.round(Number(match[1]) * unit);
 }

